import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.eFe5Lsvn.js";const i="/Mayhem/img/overview.jpg",m=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"guide/introduction.md","filePath":"guide/introduction.md"}'),s={name:"guide/introduction.md"};function n(h,t,l,d,c,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Mayhem plans time-optimal swerve autonomous paths for the 2026 FRC game, REBUILT. You place waypoints on the field; the solver finds the fastest path your drivetrain can physically drive while avoiding obstacles. <strong>MayhemLib</strong> then follows that path on the robot and recovers if the robot is bumped off it.</p><p><img src="'+i+'" alt="The Mayhem desktop app"></p><h2 id="the-three-parts" tabindex="-1">The three parts <a class="header-anchor" href="#the-three-parts" aria-label="Permalink to &quot;The three parts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Part</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Desktop app</strong> (macOS, Windows, Linux)</td><td>Where you build paths. You set up your robot and the field, place waypoints, add constraints and event markers, and press <strong>Generate</strong>.</td></tr><tr><td><strong>Solver</strong> (Python, CasADi + IPOPT)</td><td>Runs inside the app. It builds each trajectory as a time-optimal control problem, tries several routes around obstacles in parallel and keeps the fastest verified one.</td></tr><tr><td><strong>MayhemLib</strong> (Java vendordep)</td><td>Runs on the roboRIO. It loads the <code>.mtraj</code> files the app writes and follows them, with feedback, time dilation and bump recovery built in.</td></tr></tbody></table><h2 id="what-makes-it-different" tabindex="-1">What makes it different <a class="header-anchor" href="#what-makes-it-different" aria-label="Permalink to &quot;What makes it different&quot;">​</a></h2><ul><li><strong>Real limits.</strong> Motor torque-speed curves, stator current limits, wheel traction (μ), mass and moment of inertia all constrain the solution. If your robot can&#39;t accelerate that hard, the path won&#39;t ask it to.</li><li><strong>Obstacles.</strong> Draw polygon or circle obstacles. The collision check uses the robot&#39;s real bumper rectangle as it rotates, not a circle around it.</li><li><strong>Useful failures.</strong> A path that can&#39;t be solved isn&#39;t just &quot;failed&quot;. The app lists what&#39;s wrong (&quot;Waypoint 3 heading conflicts with point-at constraint&quot;) and marks the spot on the field.</li><li><strong>Bump recovery.</strong> On the robot, MayhemLib notices a hit and plans the fastest feasible bridge back onto the trajectory. It deliberately does not avoid obstacles while recovering, which keeps planning well under a millisecond on a roboRIO.</li></ul><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to &quot;Workflow&quot;">​</a></h2><ol><li><a href="/Mayhem/guide/installation">Install</a> the app and the robot library.</li><li>Create a project <a href="/Mayhem/app/projects">inside your robot code</a> at <code>src/main/deploy/mayhem/</code>.</li><li>Enter your <a href="/Mayhem/app/robot">robot&#39;s real numbers</a> and check the <a href="/Mayhem/app/field">field</a>.</li><li><a href="/Mayhem/app/paths">Build a path</a>, add <a href="/Mayhem/app/constraints">constraints</a> and <a href="/Mayhem/app/markers">markers</a>, and press <strong>Generate</strong>.</li><li><a href="/Mayhem/app/checking">Check it</a> on the timeline and graphs.</li><li>Write a few lines of <a href="/Mayhem/lib/quick-start">robot code</a> to run it.</li></ol><p>The fastest way through all of that is <a href="/Mayhem/guide/quick-start">Your first auto</a>.</p><div class="tip custom-block"><p class="custom-block-title">Coming from Choreo?</p><p>MayhemLib&#39;s API is modeled on ChoreoLib&#39;s <code>AutoFactory</code> / <code>AutoRoutine</code> / <code>AutoTrajectory</code> / <code>AutoChooser</code>, so most code ports with few changes. The main difference is that you don&#39;t write a controller. See <a href="/Mayhem/lib/from-choreo">Coming from Choreo</a>.</p></div><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Mayhem targets the <strong>2026 season</strong> (REBUILT, WPILib 2026 on roboRIO 2, Java 17) and CTRE Phoenix 6 swerve (a Tuner X <code>CommandSwerveDrivetrain</code>) with AprilTag-fused pose. Other drivetrains work through the <code>AutoFactory</code> constructor. WPILib 2027 and SystemCore support come later.</p>',13)])])}const f=e(s,[["render",n]]);export{m as __pageData,f as default};
